function s2tConvert(text) {
    if (!text) return text;
    return text.split("").map(c => S2T_MAP[c] || c).join("");
}
function t2sConvert(text) {
    if (!text) return text;
    return text.split("").map(c => T2S_MAP[c] || c).join("");
}
s2tInit();
t2sInit();

/* Load on DOM ready */
document.getElementById('zhaiList').setAttribute('data-ready', document.readyState);
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', loadContent);
} else {
    loadContent();
}